const webhook = $('Ingesta Webhook').first();
const json = webhook.json || {};
const headers = json.headers || {};

// Extrae el token desde FormData o desde el encabezado Authorization
const authHeader = headers.authorization || headers.Authorization || '';
const token = json.token || authHeader.replace(/^Bearer\s+/i, '').trim();

if (!token) {
  throw new Error('No se recibió token de autenticación (JWT) desde el frontend');
}

const documentoId = json.documento_id || ('DOC-' + (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now())));

return [{
  json: {
    documento_id: String(documentoId),
    access_token: token,
    api_base_url: json.api_base_url || 'http://host.docker.internal:8000'
  },
  binary: webhook.binary
}];

function listFrom(name) {
  try {
    const items = $(name).all();
    if (items.length === 1 && Array.isArray(items[0].json)) return items[0].json;
    return items.map((i) => i.json);
  } catch {
    return [];
  }
}
const prep = $('Preparar corrida').first().json;
const text = $input.first().json.text || '';
return [{
  json: {
    text,
    catalogo_tipos: JSON.stringify(listFrom('GET tipos activos'), null, 2),
    catalogo_colas: JSON.stringify(listFrom('GET colas activas'), null, 2),
    documento_id: prep.documento_id
  }
}];

