/**
 * Nodo Code de n8n: Construcción y sanitización estricta de IngestPayload para FastAPI.
 */
function parseGemini(raw) {
  if (raw && typeof raw === 'object' && raw.clasificacion) return raw;
  const text = typeof raw === 'string' ? raw : raw?.text || raw?.output || JSON.stringify(raw || {});
  const match = String(text).match(/\{[\s\S]*\}/);
  if (!match) return {};
  try {
    return JSON.parse(match[0]);
  } catch {
    return {};
  }
}

function listFrom(nodeName) {
  try {
    const items = $(nodeName).all();
    if (items.length === 1 && Array.isArray(items[0].json)) return items[0].json;
    return items.map((i) => i.json);
  } catch {
    return [];
  }
}

const item = $input.first();
const prep = $('Preparar corrida').first();
const gemini = parseGemini(item.json);

// 1. OBTENCIÓN Y CONVERSIÓN REAL A BASE64
let archivoBase64 = '';
let tipoArchivo = 'PDF';
try {
  const binaryObj = item.binary || prep.binary || {};
  const binaryKey = Object.keys(binaryObj)[0] || 'data';
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  archivoBase64 = buffer.toString('base64');

  const mime = (binaryObj[binaryKey]?.mimeType || '').toLowerCase();
  if (mime.includes('pdf')) tipoArchivo = 'PDF';
  else if (mime.includes('png')) tipoArchivo = 'PNG';
  else if (mime.includes('tif')) tipoArchivo = 'TIFF';
  else if (mime.includes('dcm')) tipoArchivo = 'DCM';
  else tipoArchivo = 'JPG';
} catch (e) {
  archivoBase64 = prep.binary?.data?.data || item.binary?.data?.data || '';
}

// 2. NORMALIZACIÓN DE CATÁLOGOS Y CÓDIGOS VÁLIDOS
const tiposCatalogo = listFrom('GET tipos activos');
const colasCatalogo = listFrom('GET colas activas');

const MAPA_TIPOS_CODIGO = {
  'Informe de Laboratorio': 'LABORATORIO',
  'Receta Médica': 'RECETA',
  'Informe de Estudio por Imágenes': 'IMAGENES',
  'Solicitud de Procedimiento': 'SOLICITUD_PROCEDIMIENTO',
  'Epicrisis / Informe de Alta': 'EPICRISIS',
  'Interconsulta / Derivación': 'INTERCONSULTA',
  'Informe de Anatomía Patológica': 'ANATOMIA_PATOLOGICA',
  'Protocolo Operatorio': 'PROTOCOLO_OPERATORIO',
  'Nota de Atención Ambulatoria': 'NOTA_ATENCION',
  'Otro / No clasificable': 'OTRO',
};

const clasificacion = (typeof gemini.clasificacion === 'object' && gemini.clasificacion !== null) ? gemini.clasificacion : {};
let rawTipo = clasificacion.tipo_documento || gemini.documento?.tipo || 'OTRO';
let tipoCodigo = MAPA_TIPOS_CODIGO[rawTipo] || rawTipo;

const codigosTiposValidos = new Set(tiposCatalogo.map(t => t.codigo).filter(Boolean));
if (codigosTiposValidos.size > 0 && !codigosTiposValidos.has(tipoCodigo)) {
  tipoCodigo = 'OTRO';
}

let prioridad = clasificacion.nivel_prioridad || 'Rutina';
if (!['Rutina', 'Prioritario', 'Urgente'].includes(prioridad)) {
  prioridad = prioridad === 'Normal' ? 'Rutina' : (prioridad === 'Ambiguo' ? 'Prioritario' : 'Rutina');
}

const score = Number(
  clasificacion.score_confianza_clasificacion ??
  gemini.documento?.confianza_clasificacion ??
  0.95
);

// 3. SANITIZACIÓN DE DATOS GENERALES (OBJETOS ESTRICTOS)
const datos = (typeof gemini.datos_generales === 'object' && gemini.datos_generales !== null) ? gemini.datos_generales : {};
const rawPac = (typeof datos.paciente === 'object' && datos.paciente !== null) ? datos.paciente : (typeof gemini.paciente === 'object' ? gemini.paciente : {});
const rawMed = (typeof datos.medico_solicitante === 'object' && datos.medico_solicitante !== null) ? datos.medico_solicitante : (typeof gemini.profesional === 'object' ? gemini.profesional : {});
const clinico = (typeof gemini.clinico === 'object' && gemini.clinico !== null) ? gemini.clinico : {};
const decision = (typeof gemini.decision_enrutamiento === 'object' && gemini.decision_enrutamiento !== null) ? gemini.decision_enrutamiento : {};

const pacienteLimpio = {
  rut: rawPac.rut || rawPac.identificacion || null,
  nombre: rawPac.nombre || rawPac.nombre_completo || 'Paciente no identificado',
  edad: rawPac.edad != null && !isNaN(Number(rawPac.edad)) ? Number(rawPac.edad) : null,
};

const medicoLimpio = {
  rut: rawMed.rut || null,
  nombre: rawMed.nombre || rawMed.nombre_completo || null,
  matricula: rawMed.matricula || null,
};

const diagnosticoPrincipal = datos.diagnostico_principal || clinico.hipotesis_diagnostica || 'Evaluación médica general';

// 4. SANITIZACIÓN ESTRICTA DE DETALLE CLÍNICO (PREVENCIÓN ERROR 422)
let detalleClinicoSanitizado = {};
if (gemini.detalle_clinico && typeof gemini.detalle_clinico === 'object' && !Array.isArray(gemini.detalle_clinico)) {
  for (const [key, value] of Object.entries(gemini.detalle_clinico)) {
    if (value && typeof value === 'object') {
      detalleClinicoSanitizado[key] = value;
    }
  }
}

// 5. ENRUTAMIENTO Y HITL
let destino = decision.destino_principal || 'Ficha_Clinica';
const codigosColasValidas = new Set(colasCatalogo.map(c => c.codigo).filter(Boolean));
if (codigosColasValidas.size > 0 && !codigosColasValidas.has(destino)) {
  destino = codigosColasValidas.has('Ficha_Clinica') ? 'Ficha_Clinica' : [...codigosColasValidas][0];
}

const urgente = prioridad === 'Urgente' || destino === 'Cola_Emergencia_Medica' || clinico.urgencia === true;
let hitl = Boolean(decision.requiere_auditoria_humana || gemini.metadata_control?.requiere_revision_humana);
if (score < 0.85 || tipoCodigo === 'OTRO') hitl = true;

const notificacion = urgente
  ? { canal: 'Alerta_Guardia_Medica', mensaje: `ALERTA URGENTE: ${diagnosticoPrincipal}` }
  : null;

const documentoId = prep.json.documento_id || ('DOC-' + Date.now());

return [{
  json: {
    documento_id: String(documentoId),
    archivos: [
      {
        tipo_archivo: tipoArchivo,
        archivo_base64: String(archivoBase64),
        rol: 'documento_principal',
      },
    ],
    clasificacion: {
      tipo_documento: tipoCodigo,
      especialidad: clasificacion.especialidad || rawMed.especialidad || 'Medicina General',
      nivel_prioridad: urgente ? 'Urgente' : prioridad,
      score_confianza_clasificacion: score,
    },
    datos_generales: {
      paciente: pacienteLimpio,
      medico_solicitante: medicoLimpio,
      diagnostico_principal: String(diagnosticoPrincipal),
      cie10_sugerido: datos.cie10_sugerido || clinico.codigo_cie10 || null,
    },
    detalle_clinico: detalleClinicoSanitizado,
    decision_enrutamiento: {
      destino_principal: destino,
      requiere_auditoria_humana: hitl,
      justificacion_enrutamiento: decision.justificacion_enrutamiento || (hitl ? 'Derivado a auditoría asistencial' : 'Enrutamiento automatizado'),
      notificacion_generada: notificacion,
    },
  },
}];
